public class ProductorConsumidor {
    private final Object lock = new Object();
    private boolean hayDato = false;

    public void producir() throws InterruptedException {
        synchronized (lock) {
            while (hayDato) lock.wait(); // libera monitor y espera
            hayDato = true;
            lock.notifyAll(); // despierta al consumidor
        }
    }

    public void consumir() throws InterruptedException {
        synchronized (lock) {
            while (!hayDato) lock.wait();
            hayDato = false;
            lock.notifyAll(); // despierta al productor
        }
    }
}

